document.addEventListener("DOMContentLoaded",init);let currentProducts=[];let currentSlug=null;let currentStorePhone=null;let currentStoreMessenger=null;let currentStoreWhatsapp=null;async function init(){currentSlug=getQueryParam("store");const statusEl=document.getElementById("products-status");const listEl=document.getElementById("product-list");if(!currentSlug){statusEl.textContent="No store specified. Go back to the store directory.";return}localStorage.setItem("skiri_active_store",currentSlug);const stopLoading=startLoadingMessage(statusEl);const request=Api.get("listProducts",{storeSlug:currentSlug});window.__criticalReady=request;window.__storeInfoPromise=request.then(r=>r&&r.ok?{storeName:r.storeName,logoUrl:r.storeLogoUrl}:null);const res=await request;stopLoading();if(!res.ok){showLoadFailedMessage(statusEl);return}window.__storeOpen=res.storeOpen!==false;renderStoreClosedState(window.__storeOpen);document.title=res.storeName+" — Mwakete";const location=storeLocationLabel(res.storeIsland,res.storeVillage);document.getElementById("store-name-tagline").textContent=location?`${res.storeName} | ${location}`:res.storeName;if(res.storeLogoUrl){const logoImg=document.getElementById("store-logo-img");logoImg.src=optimizedImageUrl(res.storeLogoUrl,IMG_W.logo);logoImg.alt=res.storeName;logoImg.classList.remove("hidden")}currentStorePhone=res.storePhone||null;currentStoreMessenger=res.storeMessenger||null;currentStoreWhatsapp=res.storeWhatsapp||null;const phoneLine=document.getElementById("store-phone-line");if(res.storePhone){phoneLine.textContent=res.storePhone;phoneLine.classList.remove("hidden")}document.getElementById("store-delivery-icons").innerHTML=renderDeliveryIcons({truck:res.storeDeliveryTruck,ship:res.storeDeliveryShip,airCargo:res.storeDeliveryAirCargo,pickPay:res.storeDeliveryPickPay,truckCost:res.storeDeliveryTruckCost,shipCost:res.storeDeliveryShipCost,airCargoCost:res.storeDeliveryAirCargoCost});currentProducts=res.products;if(currentProducts.length===0){statusEl.textContent="This store has no products listed yet."}else{statusEl.textContent="";listEl.innerHTML=currentProducts.map(p=>renderProductCard(p,{storeSlug:currentSlug})).join("");disableOrderingControls();fitPriceLabels(listEl);recordProductViewsOnce(currentProducts.map(p=>p.productId))}recordStoreVisitOnce(currentSlug);updateCartCount();wireProductEvents();wireGalleryScrollSync();wireProductsSearch();loadSimilarProducts();scrollToRequestedProduct()}function filterCurrentProducts(query){const q=query.trim().toLowerCase();if(!q)return currentProducts;return currentProducts.filter(p=>{const haystack=`${p.name} ${p.description||""} ${p.category||""}`.toLowerCase();return haystack.indexOf(q)!==-1})}function renderFilteredProducts(query){const statusEl=document.getElementById("products-status");const listEl=document.getElementById("product-list");const filtered=filterCurrentProducts(query);if(filtered.length===0){statusEl.textContent=query.trim()?`No products match "${query.trim()}".`:"This store has no products listed yet.";listEl.innerHTML="";return}statusEl.textContent="";listEl.innerHTML=filtered.map(p=>renderProductCard(p,{storeSlug:currentSlug})).join("");disableOrderingControls();fitPriceLabels(listEl);wireGalleryScrollSync()}function wireProductsSearch(){const form=document.getElementById("products-search-form");const input=document.getElementById("products-search-input");let debounceTimer=null;form.addEventListener("submit",e=>{e.preventDefault();clearTimeout(debounceTimer);renderFilteredProducts(input.value)});input.addEventListener("input",()=>{clearTimeout(debounceTimer);debounceTimer=setTimeout(()=>renderFilteredProducts(input.value),300)})}function scrollToRequestedProduct(){const productId=getQueryParam("product");if(!productId)return;const card=document.querySelector(`.product-card[data-product-id="${CSS.escape(productId)}"]`);if(!card)return;card.scrollIntoView({behavior:"smooth",block:"center"});card.classList.add("product-highlight");card.addEventListener("animationend",()=>card.classList.remove("product-highlight"),{once:true})}async function loadSimilarProducts(){if(currentProducts.length===0)return;const category=currentProducts[0].category||"general";const res=await Api.get("searchProducts",{category:category});if(!res.ok)return;const ownNames=currentProducts.map(p=>p.name);const similar=res.products.filter(p=>p.storeSlug!==currentSlug).filter(p=>!isBookingListing(p)).filter(p=>ownNames.some(name=>namesShareEquivalentWord(name,p.name))).slice(0,10);if(similar.length===0)return;document.getElementById("similar-products-list").innerHTML=similar.map(p=>renderBrowseProductCard(p,{cardClass:"similar-product-card"})).join("");document.getElementById("similar-section").classList.remove("hidden");fitPriceLabels(document.getElementById("similar-products-list"));recordProductViewsOnce(similar.map(p=>p.productId))}function showAddingToCartState(btn){btn.disabled=true;btn.classList.add("btn-adding");btn.innerHTML='Adding<span class="btn-saving-dots"><span></span><span></span><span></span></span>';setTimeout(()=>{btn.disabled=false;btn.classList.remove("btn-adding");btn.textContent="Add to Cart"},900)}async function onRequestBooking(btn){const productId=btn.dataset.productId;const product=currentProducts.find(p=>p.productId===productId);if(!product)return;const statusEl=document.getElementById(`booking-status-${productId}`);const select=document.getElementById(`variety-${productId}`);const startInput=document.getElementById(`start-${productId}`);const endInput=document.getElementById(`end-${productId}`);const nameInput=document.getElementById(`name-${productId}`);const phoneInput=document.getElementById(`phone-${productId}`);const notesInput=document.getElementById(`notes-${productId}`);const customerName=nameInput.value.trim();const customerPhone=phoneInput.value.trim();if(!customerName||!customerPhone){setFormStatus(statusEl,"Please enter your name and phone number.","error");return}if(!startInput.value||!endInput.value){setFormStatus(statusEl,"Please choose a start and end date.","error");return}if(startInput.value>=endInput.value){setFormStatus(statusEl,"End date must be after start date.","error");return}btn.disabled=true;btn.innerHTML='Sending<span class="btn-saving-dots"><span></span><span></span><span></span></span>';setFormStatus(statusEl,"");const res=await Api.post("createBookingRequest",{storeSlug:currentSlug,productId:productId,variantId:select.value,startDate:startInput.value,endDate:endInput.value,customerName:customerName,customerPhone:customerPhone,notes:notesInput.value.trim()});if(!res.ok){setFormStatus(statusEl,res.error||"Could not send this booking request.","error");btn.disabled=false;btn.textContent="Request Booking";return}btn.textContent="Requested";setFormStatus(statusEl,"Booking request sent — the vendor will confirm or decline.","success");renderBookingVendorContact(productId)}function renderBookingVendorContact(productId){const contactEl=document.getElementById(`booking-contact-${productId}`);if(!contactEl)return;contactEl.innerHTML=sellerContactButtons({phone:currentStorePhone,whatsapp:currentStoreWhatsapp,messenger:currentStoreMessenger});contactEl.classList.remove("hidden");wireContactUnavailable()}function wireProductEvents(){document.getElementById("product-list").addEventListener("click",e=>{const thumbBtn=e.target.closest(".product-gallery-thumb");if(thumbBtn){const card=thumbBtn.closest(".product-card");const track=card.querySelector(".product-gallery-track");if(track)track.scrollTo({left:track.clientWidth*Number(thumbBtn.dataset.index),behavior:"smooth"});card.querySelectorAll(".product-gallery-thumb").forEach(b=>b.classList.remove("active"));thumbBtn.classList.add("active");return}const bookingBtn=e.target.closest(".request-booking-btn");if(bookingBtn){onRequestBooking(bookingBtn);return}const btn=e.target.closest(".add-to-cart-btn");if(!btn)return;const productId=btn.dataset.productId;const product=currentProducts.find(p=>p.productId===productId);if(!product)return;const select=document.getElementById(`variety-${productId}`);const qtyInput=document.getElementById(`qty-${productId}`);const variant=product.variants.find(v=>v.variantId===select.value);if(!variant)return;const qty=Math.max(1,parseInt(qtyInput.value,10)||1);const prevDistinct=Cart.getDistinctProductCount(currentSlug);Cart.addItem(currentSlug,{variantId:variant.variantId,productId:product.productId,label:`${product.name} — ${variant.label}`,unitPrice:variant.price,qty:qty});showAddingToCartState(btn);updateCartCount();animateCartOnAdd(prevDistinct,Cart.getDistinctProductCount(currentSlug));const feedback=document.getElementById("cart-feedback");feedback.textContent=`Added ${qty} × ${product.name} (${variant.label}) to your cart.`;setTimeout(()=>{feedback.textContent=""},4e3)})}function wireGalleryScrollSync(){document.querySelectorAll(".product-gallery-track").forEach(track=>{track.addEventListener("scroll",()=>{const index=Math.round(track.scrollLeft/track.clientWidth);const card=track.closest(".product-card");card.querySelectorAll(".product-gallery-thumb").forEach((b,i)=>b.classList.toggle("active",i===index))},{passive:true})})}function updateCartCount(){const el=document.getElementById("cart-link");el.querySelector("#cart-count").textContent=Cart.getItemCount(currentSlug);const n=Cart.getDistinctProductCount(currentSlug);el.classList.toggle("cart-fab--bold",n>=1);el.classList.toggle("cart-fab--corner",n>=2)}function animateCartOnAdd(prev,next){const el=document.getElementById("cart-link");if(!el||next<3)return;const cls=prev<3?"cart-fab--flash2":"cart-fab--blink";el.classList.remove("cart-fab--flash2","cart-fab--blink");void el.offsetWidth;el.classList.add(cls);el.addEventListener("animationend",()=>el.classList.remove(cls),{once:true})}function renderStoreClosedState(open){const existing=document.getElementById("store-closed-banner");if(open){if(existing)existing.remove();document.body.classList.remove("store-is-closed");return}document.body.classList.add("store-is-closed");if(!existing){const banner=document.createElement("div");banner.id="store-closed-banner";banner.className="store-closed-banner";banner.setAttribute("role","status");banner.innerHTML='<span class="store-closed-pill">Closed</span>'+"<span>This store is not taking orders right now. You can still browse and chat with them.</span>";const anchor=document.getElementById("store-name-tagline");if(anchor&&anchor.parentNode)anchor.parentNode.insertBefore(banner,anchor.nextSibling)}disableOrderingControls()}function disableOrderingControls(){if(!document.body.classList.contains("store-is-closed"))return;document.querySelectorAll(".add-to-cart-btn, .request-booking-btn").forEach(btn=>{btn.disabled=true;btn.title="This store is closed right now"})}